#include <stdio.h>
#include <stdint.h>
#include <limits.h>

int main(void) {
    printf("%d\n", 7 / 2);          // entero entre entero: se descarta lo fraccionario
    printf("%f\n", 7 / 2.0);        // un lado es double: división con coma
    uint8_t b = 255;
    b = b + 1;                      // 256 no cabe en 8 bits
    printf("%d\n", b);
    printf("%u\n", UINT_MAX + 1u);  // el mayor unsigned int, más uno
    printf("%zu %zu %zu\n", sizeof(char), sizeof(int), sizeof(double));
    return 0;
}

let sinValor;
console.log(sinValor);                                   // undefined
const casillero = { fila: 3 };
console.log(casillero.columna);                          // undefined: esa propiedad no existe
console.log(typeof sinValor, typeof null);               // undefined object
let ocupante = null;                                     // vacío a propósito
console.log(ocupante === null, ocupante === undefined);  // true false
console.log(null === undefined, null == undefined);      // false true
try {
  console.log(ocupante.nombre);                          // leer algo de «nada»
} catch (e) {
  console.log(e.name + ": " + e.message);                // el texto exacto depende del motor
}

console.log("42", "->", typeof (42));
console.log("3.14", "->", typeof (3.14));
console.log("NaN", "->", typeof (NaN));
console.log("'hola'", "->", typeof ("hola"));
console.log("true", "->", typeof (true));
console.log("undefined", "->", typeof (undefined));
console.log("null", "->", typeof (null));
console.log("10n", "->", typeof (10n));
console.log("[1, 2]", "->", typeof ([1, 2]));
console.log("{ a: 1 }", "->", typeof ({ a: 1 }));
console.log("function () {}", "->", typeof (function () {}));

console.log(9007199254740993);     // como number: 9007199254740992, se corrompe
console.log(9007199254740993n);    // como BigInt: exacto
console.log(2n ** 64n);            // 18446744073709551616n
console.log(5n / 2n);              // 2n: sin decimales
console.log(typeof 10n);           // bigint
try {
  console.log(1n + 1);             // mezclar BigInt con number
} catch (e) {
  console.log(e.name + ": " + e.message);
}

